import { useEffect, useState } from 'react';
import { Grid, Box, Typography, Alert } from '@mui/material';
import SimpleStockChart from './SimpleStockChart';
import FinanceService from '../../services/FinanceService';
import WarningAmberIcon from '@mui/icons-material/WarningAmber';
import { useUser } from "../../context/UserContext";

const StockGrid = ({ themeMode, language }) => {
  const { userState } = useUser();

  const [stockData, setStockData] = useState({
    ASX200: { data: null, error: null, loading: true },
    SSE: { data: null, error: null, loading: true },
    SP500: { data: null, error: null, loading: true },
    FTSE: { data: null, error: null, loading: true },
  });

  const tickers = {
    ASX200: '^AXJO',
    SSE: '000001.SS',
    SP500: '^GSPC',
    FTSE: '^FTSE',
  };

  useEffect(() => {
    const fetchStockData = async () => {
      // 如果 access 为空，则不执行后续操作
      if (!userState.access) {
        return;
      }
      Object.keys(tickers).forEach(async (key) => {
        try {
          const data = await FinanceService.get_stock_history_data(tickers[key], userState.access);
          
          // 如果是SSE数据，将最新一天的volume强制调为0
          if (key === 'SSE' && data && data.history && data.history.length > 0) {
            const modifiedData = {
              ...data,
              history: data.history.map((item, index) => {
                // 如果是最后一天（最新数据），将volume设为0
                if (index === data.history.length - 1) {
                  return {
                    ...item,
                    Volume: 0
                  };
                }
                return item;
              })
            };
            setStockData((prevData) => ({
              ...prevData,
              [key]: { data: modifiedData, error: null, loading: false },
            }));
          } else {
            setStockData((prevData) => ({
              ...prevData,
              [key]: { data, error: null, loading: false },
            }));
          }
        } catch (error) {
          console.error(`Failed to fetch data for ${key}:`, error);
          setStockData((prevData) => ({
            ...prevData,
            [key]: { data: null, error: 'Failed to load data', loading: false },
          }));
        }
      });
    };

    fetchStockData();
  }, [userState.access]);

  const calculateChange = (data) => {
    if (!data || data.history.length < 2) return null;
    const lastClose = data.history[data.history.length - 1].Close;
    const secondLastClose = data.history[data.history.length - 2].Close;
    const change = lastClose - secondLastClose;
    const percentageChange = (change / secondLastClose) * 100;

    return { change, percentageChange };
  };

  const stockItems = [
    { title: 'ASX 200', key: 'ASX200' },
    { title: 'SSE Composite', key: 'SSE' },
    { title: 'S&P 500', key: 'SP500' },
    { title: 'FTSE 100', key: 'FTSE' },
  ];

  return (
    <Grid container spacing={2} sx={{ height: '100%' }}>
      {stockItems.map((item, index) => {
        const { data, error, loading } = stockData[item.key];
        const changeData = calculateChange(data);
        
        return (
          <Grid key={index} item xs={12} sm={6} sx={{ height: { xs: '25%', sm: '50%' } }}>
            <Box
              sx={{
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'center',
                alignItems: 'center',
                height: '100%',
              }}
            >
              <Box
                sx={{
                  width: '100%',
                  height: '280px',
                  display: 'flex',
                  justifyContent: 'center',
                  alignItems: 'center',
                }}
              >
                {error ? (
                    <WarningAmberIcon
                    sx={{
                        color: 'error.main',
                        fontSize: 48, // 设置图标大小
                    }}
                    />
                ) : (
                  <SimpleStockChart 
                    data={data} 
                    title={item.title}
                    changeData={changeData}
                    language={language}
                    loading={loading}
                  />
                )}
              </Box>
            </Box>
          </Grid>
        );
      })}
    </Grid>
  );
};

export default StockGrid;