import { useEffect, useRef, useContext } from 'react';
import { createChart } from 'lightweight-charts';
import { Card, Box, Typography, CircularProgress, useMediaQuery } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import { SettingsContext } from '../../context/SettingsContext';

const SimpleStockChart = ({ data, title, changeData, language, loading = false }) => {
  const chartContainerRef = useRef(null);
  const legendRef = useRef(null);
  const { themeMode } = useContext(SettingsContext);

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));

  const calculateChange = (data) => {
    if (!data || data.history.length < 2) return null;
    const lastClose = data.history[data.history.length - 1].Close;
    const secondLastClose = data.history[data.history.length - 2].Close;
    const change = lastClose - secondLastClose;
    const percentageChange = (change / secondLastClose) * 100;

    return { change, percentageChange };
  };

  // 如果没有传入changeData，则计算
  const finalChangeData = changeData || calculateChange(data);

  useEffect(() => {
    if (!data || !data.history || data.history.length === 0) {
      console.error('Invalid data format or no data available');
      return;
    }

    const isDarkMode = themeMode === 'dark';
    const isChineseLanguage = language === 'cn';

    const chartOptions = {
      width: chartContainerRef.current.clientWidth,
      layout: {
        background: { color: 'transparent', type: 'solid' },
        textColor: isDarkMode ? '#d1d4dc' : '#000000',
      },
      grid: {
        vertLines: { visible: false },
        horzLines: { visible: false },
      },
      crosshair: {
        mode: 1,
        vertLine: {
          color: '#758696',
          width: 1,
          style: 1,
          labelBackgroundColor: isDarkMode ? '#1a1a1a' : '#FFFFFF',
        },
        horzLine: {
          color: '#758696',
          width: 1,
          style: 1,
          labelBackgroundColor: isDarkMode ? '#1a1a1a' : '#FFFFFF',
        },
      },
      timeScale: {
        borderVisible: false,
      },
      rightPriceScale: {
        // borderColor: isDarkMode ? '#2B2B43' : '#E0E0E0',
        borderVisible: false,
        scaleMargins: {
          top: 0.1,
          bottom: 0.2,
        },
      }
    };

    const chart = createChart(chartContainerRef.current, chartOptions);

    const mainPriceScale = chart.priceScale('right');
    const volumePriceScale = chart.priceScale('left');
    volumePriceScale.applyOptions({
      scaleMargins: {
        top: 0.8,
        bottom: 0,
      },
      visible: false,
    });

    // 在中文环境，红涨绿跌；英文环境，绿涨红跌
    const candleSeries = chart.addCandlestickSeries({
      upColor: isChineseLanguage ? '#ef5350' : '#26a69a',
      downColor: isChineseLanguage ? '#26a69a' : '#ef5350',
      borderVisible: false,
      wickUpColor: isChineseLanguage ? '#ef5350' : '#26a69a',
      wickDownColor: isChineseLanguage ? '#26a69a' : '#ef5350',
    });

    const volumeSeries = chart.addHistogramSeries({
      color: '#26a69a50',
      priceFormat: {
        type: 'volume',
      },
      priceScaleId: 'left',
    });

    const chartData = data.history.map((item) => ({
      time: new Date(item.Date).getTime() / 1000,
      open: item.Open,
      high: item.High,
      low: item.Low,
      close: item.Close,
    }));

    const volumeData = data.history.map((item) => ({
      time: new Date(item.Date).getTime() / 1000,
      value: item.Volume,
      color:
        item.Close >= item.Open
          ? isChineseLanguage
            ? '#ef535050'
            : '#26a69a50'
          : isChineseLanguage
          ? '#26a69a50'
          : '#ef535050',
    }));

    candleSeries.setData(chartData);
    volumeSeries.setData(volumeData);

    // 创建并样式化图例容器
    const legend = document.createElement('div');
    legend.style.position = 'absolute';
    legend.style.left = '1px';
    legend.style.top = '1px';
    legend.style.fontSize = isMobile ? '10px' : '12px';
    legend.style.gap = '8px';
    legendRef.current = legend;
    chartContainerRef.current.appendChild(legend);

    // 订阅 crosshair 移动事件
    chart.subscribeCrosshairMove((param) => {
      if (!param.time || !param.point) {
        legend.style.display = 'none';
        return;
      }

      const candleData = param.seriesData.get(candleSeries);
      const volData = param.seriesData.get(volumeSeries);

      if (!candleData || !volData) {
        legend.style.display = 'none';
        return;
      }

      legend.style.display = 'flex';

      // 根据语言，对日期做不同格式化
      const date = new Date(param.time * 1000);

      let formattedDate;
      if (isChineseLanguage) {
        // yyyy/mm/dd
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        formattedDate = `${year}/${month}/${day}`;
      } else {
        // dd/Mon/yyyy (Mon 为英文缩写)
        const day = date.getDate();
        const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
        const month = monthNames[date.getMonth()];
        const year = date.getFullYear();
        formattedDate = `${day}/${month}/${year}`;
      }

      const formatPrice = (price) => price.toFixed(2);
      const formatVolume = (volume) => {
        if (volume >= 1000000) {
          return (volume / 1000000).toFixed(2) + 'M';
        } else if (volume >= 1000) {
          return (volume / 1000).toFixed(2) + 'K';
        }
        return volume.toFixed(0);
      };

      // 根据语言切换标签
      const OLabel = isChineseLanguage ? '开' : 'O';
      const HLabel = isChineseLanguage ? '高' : 'H';
      const LLabel = isChineseLanguage ? '低' : 'L';
      const CLabel = isChineseLanguage ? '收' : 'C';
      const VLabel = isChineseLanguage ? '量' : 'V';

      legend.innerHTML = `
        <span>${formattedDate}</span>
        <span>${OLabel}: ${formatPrice(candleData.open)}</span>
        <span>${HLabel}: ${formatPrice(candleData.high)}</span>
        <span>${LLabel}: ${formatPrice(candleData.low)}</span>
        <span>${CLabel}: ${formatPrice(candleData.close)}</span>
        <span>${VLabel}: ${formatVolume(volData.value)}</span>
      `;
    });

    // 隐藏 TradingView logo
    const style = document.createElement('style');
    style.textContent = `
      #tv-attr-logo {
        display: none !important;
      }
    `;
    document.head.appendChild(style);

    // 处理图表自适应
    const handleResize = () => {
      chart.applyOptions({
        width: chartContainerRef.current.clientWidth,
      });
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      document.head.removeChild(style);
      if (legendRef.current && chartContainerRef.current) {
        chartContainerRef.current.removeChild(legendRef.current);
      }
      chart.remove();
    };
  }, [data, themeMode, language]);

  return (
    <Card
      sx={{
        width: '100%',
        height: '280px',
        position: 'relative',
        overflow: 'hidden',
        boxShadow: 2,
        display: 'flex',
        borderRadius: 2,
        flexDirection: 'column',
      }}
    >
      {/* 标题和涨跌信息 - 在Card上方 */}
      {title && (
        <Box
          sx={{
            px: 2,
            py: 1.2 ,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            // borderBottom: '1px solid',
            // borderColor: 'divider',
            minHeight: '40px',
          }}
        >
          <Typography
            variant="h6"
            sx={{
              fontWeight: 700,
              color: themeMode === 'dark' ? 'white' : 'black',
              fontSize: '1.1rem',
              letterSpacing: '0.7px',
            }}
          >
            {title}
          </Typography>
          {finalChangeData && (
            <Box
              sx={{
                display: 'flex',
                gap: 0.5,
              }}
            >
              <Typography
                variant="subtitle2"
                sx={{
                  fontWeight: 600,
                  color: finalChangeData.change >= 0
                    ? language === 'cn' ? '#ef5350' : '#26a69a' // Red : Green for 'cn'
                    : language === 'cn' ? '#26a69a' : '#ef5350', // Green : Red for 'cn'
                  fontSize: '1rem',
                  fontFamily: 'monospace',
                }}
              >
                {finalChangeData.change >= 0 ? '+' : ''}
                {finalChangeData.change.toFixed(2)}
              </Typography>
              <Typography
                variant="subtitle2"
                sx={{
                  fontWeight: 600,
                  color: finalChangeData.change >= 0
                    ? language === 'cn' ? '#ef5350' : '#26a69a' // Red : Green for 'cn'
                    : language === 'cn' ? '#26a69a' : '#ef5350', // Green : Red for 'cn'
                  fontSize: '1rem',
                  fontFamily: 'monospace',
                }}
              >
                ({finalChangeData.change >= 0 ? '+' : ''}
                {finalChangeData.percentageChange.toFixed(2)}%)
              </Typography>
            </Box>
          )}
        </Box>
      )}

      {/* 图表容器 */}
      <Box
        sx={{
          flex: 1,
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
        }}
      >
        {loading || !data ? (
          <CircularProgress color="primary" />
        ) : (
          <div
            ref={chartContainerRef}
            style={{
              width: '100%',
              height: '100%',
              position: 'relative',
            }}
          />
        )}
      </Box>
    </Card>
  );
};

export default SimpleStockChart;
